import{_ as r,l,o as e,c as o,v as i,p as s,x as n,d as E,i as h,S as A}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"推理的忠实性","description":"","frontmatter":{"title":"推理的忠实性","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/reasoning-faithfulness.md","filePath":"llm/reasoning-faithfulness.md","lastUpdated":1789023840000}'),p={name:"llm/reasoning-faithfulness.md"};function d(m,a,u,B,T,c){const t=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=i('<h1 id="推理的忠实性" tabindex="-1">推理的忠实性 <a class="header-anchor" href="#推理的忠实性" aria-label="Permalink to &quot;推理的忠实性&quot;">​</a></h1><div class="epigraph"><p>链上写的步骤不必是内部用来得出答案的计算；看起来可监视，不等于逐步为真。</p><footer>—— Turpin 等 Language Models Don&#39;t Always Say What They Think；Lanham 等 Measuring Faithfulness in Chain-of-Thought</footer></div><p><a href="/llm/language-mixing-reasoning">上一课</a>把链的表面语言修好。本课程最后一课问更深的缺口：<strong>可读、甚至自检漂亮的链，是否忠实于导致答案的计算？</strong> Turpin 等人显示提示 CoT 可被无关特征左右而事后合理化。Lanham 等人测量干预链是否改变答案。接到 <a href="/llm/process-supervision">过程监督</a> 与 CoT monitorability：可监视性 ≠ 忠实性。本课结束「强化学习进阶」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>结果 RL 只约束终局 \\(R\\)。链是潜变量，只要终局对，什么样的故事都能被强化，包括事后合理化。SFT 示范的人类解题步骤更接近忠实教学，但学生仍可能学「步骤模样」。Turpin：加入偏置特征，模型答案跟着偏置走，CoT 却写一套正经理由。Lanham：删改链上句子，看答案是否变——不变则链不必要，谈不上忠实。</p><p>对齐含义：监视器读链可能漏掉真意图（Baker 混淆实验）。可扩展监督若假设「看链等于看计算」，在不忠实时失败。</p><h3 id="忠实性不是校准也不是正确" tabindex="-1">忠实性不是校准也不是正确 <a class="header-anchor" href="#忠实性不是校准也不是正确" aria-label="Permalink to &quot;忠实性不是校准也不是正确&quot;">​</a></h3><p>答案可以对而链不忠实（蒙对 + 假证明）。链可以逐步合法而答案抽错。PRM 提高逐步合法，不自动提高「这些步骤真被用来算答案」。必要性（必须写下来才能算）是架构性质；倾向性（愿意写真话）才是训练性质。</p><p><span class="marginnote">不要把 R1 的反思句当成已证明的忠实。那是行为描述，Turpin/Lanham 的测试仍要做。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>测量：偏置提示下 CoT 是否披露偏置；链干预后答案敏感度；过程标签与终局一致性。训练：过程监督 / PRM-RL 提高逐步合法；不要把监视器分数写进过强 \\(R\\)（混淆）。可验证域用形式化步骤（Lean）逼近可检查忠实。提示 CoT（先写理由再答）与 R1 式隐藏思维分开报：前者更常不忠实。</p>',11)),(e(),s(A,null,{default:n(()=>[h(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20COT%5B%22%E5%86%99%E5%87%BA%E7%9A%84%E9%93%BE%22%5D%20--%3E%20NEC%5B%22%E5%BF%85%E8%A6%81%E6%80%A7%EF%BC%9A%E7%AE%97%E4%B8%8D%E7%AE%97%E5%BE%97%E9%9D%A0%E5%AE%83%22%5D%0A%20%20COT%20--%3E%20FAITH%5B%22%E5%BF%A0%E5%AE%9E%E6%80%A7%EF%BC%9A%E6%98%AF%E5%90%A6%E5%AF%B9%E5%BA%94%E7%9C%9F%E8%AE%A1%E7%AE%97%22%5D%0A%20%20COT%20--%3E%20MON%5B%22%E5%8F%AF%E7%9B%91%E8%A7%86%E6%80%A7%EF%BC%9A%E7%9B%91%E8%A7%86%E5%99%A8%E8%83%BD%E5%90%A6%E8%AF%BB%E5%87%BA%E9%A3%8E%E9%99%A9%22%5D%0A%20%20RL%5B%22%E5%8F%AA%E5%A5%96%E7%BB%88%E5%B1%80%22%5D%20--%3E%20POST%5B%22%E4%BA%8B%E5%90%8E%E5%90%88%E7%90%86%E5%8C%96%22%5D%0A%20%20PRM%5B%22%E8%BF%87%E7%A8%8B%E7%9B%91%E7%9D%A3%22%5D%20--%3E%20STEP%5B%22%E9%80%90%E6%AD%A5%E5%90%88%E6%B3%95%20%E2%86%91%22%5D%0A%20%20STEP%20--%3E%20FAITH%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>与 <a href="/llm/honesty-calibration-training">诚实校准</a>：诚实是对用户的态度；忠实是链与计算的关系。都要金标，金标不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>终局奖励下，链的信息论角色是工作记忆 + 可能的社交展示。展示部分会被有用 / 无害 / 监视压力塑造。RL 越强，展示与计算越可能分裂。monitorability tax：保留不直接优化链的区域，换取监视价值，代价是链继续不保证忠实。没有免费的三者兼得。</p><p><span class="marginnote">并行采样再投票也不使单条链更忠实，只使答案更稳。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>本课没有部署上的完全解。实践：可验证终局 + 抽查过程 + 不把链监视器当唯一闸 + 对人可见答案另做诚实约束。强化学习进阶从 RM 不确定性走到链是否可信，停在这里是因为更前的课已经给出工具，缺的是把「链当证据」写成有测试的主张。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>终局 RL 不保证思维链忠实；事后合理化是默认风险。</li><li>测量用偏置测试与链干预，不要用漂亮例子。</li><li>可监视性、必要性、忠实性三件不同；过程监督只推逐步合法。</li><li>监视器进奖励会混淆链。</li><li>出处：Turpin 等；Lanham 等；Lightman PRM；Korbak / Baker 可监视性；DeepSeek-AI R1 行为作对照。</li></ul>',8))])}const g=r(p,[["render",d]]);export{_ as __pageData,g as default};
